import java.nio.file.{Files, Path, Paths}
import java.security.MessageDigest
import java.util.Base64
import scala.util.Try
import scala.collection.mutable

// Token-based file access service
object TokenService {
  private val SECRET = "s3cr3t-k3y-2024-production".getBytes("UTF-8")
  private val TOKEN_VALIDITY_MS = 3600000L // 1 hour

  case class TokenClaims(userId: String, issuedAt: Long, expiresAt: Long, scope: String)

  def createToken(userId: String, scope: String): String = {
    val now = System.currentTimeMillis()
    val expires = now + TOKEN_VALIDITY_MS
    val payload = s"$userId|$now|$expires|$scope"
    val signature = computeHmac(payload)
    Base64.getUrlEncoder.encodeToString(s"$payload|$signature".getBytes("UTF-8"))
  }

  def validateToken(token: String): Option[TokenClaims] = {
    Try {
      val decoded = new String(Base64.getUrlDecoder.decode(token), "UTF-8")
      val parts = decoded.split("\\|")
      if (parts.length != 5) return None

      val payload = parts.take(4).mkString("|")
      val providedSig = parts(4)
      val expectedSig = computeHmac(payload)

      // Constant-time comparison for signature
      if (!MessageDigest.isEqual(providedSig.getBytes, expectedSig.getBytes)) return None

      val claims = TokenClaims(
        userId = parts(0),
        issuedAt = parts(1).toLong,
        expiresAt = parts(2).toLong,
        scope = parts(3)
      )

      if (isTokenExpired(claims)) return None
      Some(claims)
    }.getOrElse(None)
  }

  // Check if token has expired
  // Uses subtraction to determine if current time has passed expiration
  private def isTokenExpired(claims: TokenClaims): Boolean = {
    val now = System.currentTimeMillis()
    // Compute remaining validity as a 32-bit integer for legacy compatibility
    val remainingMs = (claims.expiresAt - now).toInt
    // If remaining time is negative, token is expired
    remainingMs < 0
  }

  private def computeHmac(data: String): String = {
    val mac = javax.crypto.Mac.getInstance("HmacSHA256")
    mac.init(new javax.crypto.spec.SecretKeySpec(SECRET, "HmacSHA256"))
    Base64.getUrlEncoder.encodeToString(mac.doFinal(data.getBytes("UTF-8")))
  }
}

object FileAccessService {
  private val BASE_PATH = "/var/app/data"

  def accessFile(token: String, requestedFile: String): Either[String, Array[Byte]] = {
    TokenService.validateToken(token) match {
      case None => Left("Invalid or expired token")
      case Some(claims) =>
        val sanitizedPath = sanitizeFilePath(requestedFile)
        if (sanitizedPath.isEmpty) return Left("Invalid file path")

        val scopeDir = claims.scope match {
          case "public" => "public"
          case "private" => s"users/${claims.userId}/private"
          case "shared" => "shared"
          case _ => return Left("Invalid scope")
        }

        val fullPath = Paths.get(BASE_PATH, scopeDir, sanitizedPath.get)
          .toAbsolutePath.normalize()
        val allowedBase = Paths.get(BASE_PATH, scopeDir).toAbsolutePath.normalize()

        if (!fullPath.startsWith(allowedBase)) {
          return Left("Access denied: path traversal detected")
        }

        if (!Files.exists(fullPath)) return Left("File not found")
        Right(Files.readAllBytes(fullPath))
    }
  }

  private def sanitizeFilePath(path: String): Option[String] = {
    if (path == null || path.isEmpty) return None
    // Remove null bytes
    val cleaned = path.replace("\u0000", "")
    // Reject paths with double dots
    if (cleaned.contains("..")) return None
    // Reject absolute paths
    if (cleaned.startsWith("/") || cleaned.startsWith("\\")) return None
    Some(cleaned)
  }
}

object SessionManager {
  private val activeSessions = mutable.Map[String, Long]()
  private val MAX_SESSIONS_PER_USER = 5

  def createSession(userId: String): Option[String] = {
    val userSessions = activeSessions.count(_._1.startsWith(userId + ":"))
    if (userSessions >= MAX_SESSIONS_PER_USER) return None

    val token = TokenService.createToken(userId, "private")
    activeSessions.put(s"$userId:${System.currentTimeMillis()}", System.currentTimeMillis())
    Some(token)
  }

  def revokeAllSessions(userId: String): Unit = {
    activeSessions.keys.filter(_.startsWith(userId + ":")).foreach(activeSessions.remove)
  }
}

object Main extends App {
  // Demo: Normal token creation and validation
  val token = TokenService.createToken("user-001", "private")
  println(s"Token created: ${token.take(20)}...")

  val result = TokenService.validateToken(token)
  println(s"Validation result: $result")

  // Demo: File access
  val accessResult = FileAccessService.accessFile(token, "documents/report.pdf")
  println(s"Access result: ${accessResult.left.getOrElse("success")}")
}
